actions.script:
function hasTurnstileIframe(){var iframes=document.querySelectorAll('iframe');for(var i=0;i<iframes.length;i++){if(iframes[i].src&&iframes[i].src.indexOf('challenges.cloudflare.com')!==-1)return true;}return false;}
async function requestTurnstileFocus(){return new Promise(function(resolve){var timeout=setTimeout(function(){window.removeEventListener('message',handler);resolve({success:false,reason:'timeout'});},40000);function handler(event){if(event.source===window&&event.data&&event.data.type==='TURNSTILE_FOCUS_RESPONSE'){clearTimeout(timeout);window.removeEventListener('message',handler);resolve(event.data);}}window.addEventListener('message',handler);window.postMessage({type:'TURNSTILE_FOCUS_REQUEST'},'*');});}
function findMetricInModal(modal,labelText){var allEls=[].slice.call(modal.querySelectorAll('*'));for(var i=0;i<allEls.length;i++){var el=allEls[i];if(el.children.length===0&&el.textContent.trim()===labelText){var container=el.parentElement;for(var t=0;t<8;t++){if(!container||container===document.body)break;var candidates=[].slice.call(container.querySelectorAll('span,div,p')).filter(function(e){var txt=e.textContent.trim();if(txt===labelText)return false;if(e.children.length>1)return false;return /^\$?[\d.,]+[KMB]?$/i.test(txt);});if(candidates.length>0)return candidates[0].textContent.trim();container=container.parentElement;}}}return null;}
function extractTableInModal(modal,headingText){var tables=[].slice.call(modal.querySelectorAll('table'));for(var t=0;t<tables.length;t++){var thead=tables[t].querySelector('thead');if(thead&&thead.textContent.indexOf(headingText)!==-1){var rows=[].slice.call(tables[t].querySelectorAll('tbody tr'));return rows.map(function(tr){return[].slice.call(tr.querySelectorAll('td')).map(function(td){return td.textContent.trim();});}).filter(function(r){return r.length>0;});}}var allEls=[].slice.call(modal.querySelectorAll('h2,h3,h4,div,span'));for(var i=0;i<allEls.length;i++){var el=allEls[i];if(el.textContent.trim()===headingText&&el.children.length<=3){var section=el.parentElement;for(var s=0;s<6;s++){if(!section||section===document.body)break;var table=section.querySelector('table');if(table){var rows=[].slice.call(table.querySelectorAll('tbody tr'));if(rows.length===0)rows=[].slice.call(table.querySelectorAll('tr'));return rows.map(function(tr){return[].slice.call(tr.querySelectorAll('td')).map(function(td){return td.textContent.trim();});}).filter(function(r){return r.length>0;});}section=section.parentElement;}}}return[];}
function parseMetricText(text){text=text.replace(/[$,]/g,'');var match=text.match(/([\d.]+)\s*([KMB])?/i);if(!match)return 0;var num=parseFloat(match[1]);var suffix=(match[2]||'').toUpperCase();if(suffix==='K')return num*1000;if(suffix==='M')return num*1000000;if(suffix==='B')return num*1000000000;return num;}
function extractGraphData(modal){try{var xTicks=modal.querySelectorAll('.recharts-xAxis .recharts-cartesian-axis-tick');var yTicks=modal.querySelectorAll('.recharts-yAxis .recharts-cartesian-axis-tick');if(!xTicks.length||!yTicks.length)return null;var curvePath=modal.querySelector('.recharts-curve.recharts-area-curve');if(!curvePath)return null;var d=curvePath.getAttribute('d');if(!d)return null;var pathMatches=d.match(/[ML]([\d.]+),([\d.]+)/g);if(!pathMatches)return null;var curvePoints=pathMatches.map(function(p){var coords=p.slice(1).split(',').map(Number);return{x:coords[0],y:coords[1]};});var yScaleValues=[].slice.call(yTicks).map(function(tick){return parseMetricText(tick.querySelector('tspan').textContent.trim());});var maxValue=Math.max.apply(null,yScaleValues);var rechartsWrapper=modal.querySelector('.recharts-wrapper');var clip=rechartsWrapper?rechartsWrapper.querySelector('clipPath rect'):modal.querySelector('clipPath rect');if(!clip)return null;var chartTop=parseFloat(clip.getAttribute('y'));var chartHeight=parseFloat(clip.getAttribute('height'));function yToValue(y){var ratio=1-(y-chartTop)/chartHeight;return Math.round(ratio*maxValue);}var xPositions=[].slice.call(xTicks).map(function(tick){return{month:tick.querySelector('tspan').textContent.trim(),x:parseFloat(tick.querySelector('text').getAttribute('x'))};});var graphResult={};curvePoints.forEach(function(point){var closest=xPositions[0];var minDist=Math.abs(point.x-closest.x);for(var j=1;j<xPositions.length;j++){var dist=Math.abs(point.x-xPositions[j].x);if(dist<minDist){minDist=dist;closest=xPositions[j];}}graphResult[closest.month]=yToValue(point.y);});return graphResult;}catch(e){return null;}}
async function waitForModalWithFocusQueue(maxRetries){for(var attempt=0;attempt<maxRetries;attempt++){var modal=null;var startTime=Date.now();var focusRequested=false;var modalTimeout=40000;await new Promise(function(r){setTimeout(r,2000);});if(hasTurnstileIframe()&&!focusRequested){focusRequested=true;var focusResult=await requestTurnstileFocus();if(focusResult.reason==='modal_appeared'||focusResult.reason==='solved'||focusResult.reason==='no_turnstile'){modal=document.querySelector('.ReactModalPortal [role="dialog"]')||document.querySelector('[class*="ReactModal__Content"]');if(modal&&modal.textContent.indexOf('Organic traffic')!==-1){return{success:true,modal:modal,attempts:attempt+1};}}}while(Date.now()-startTime<modalTimeout){modal=document.querySelector('.ReactModalPortal [role="dialog"]')||document.querySelector('[class*="ReactModal__Content"]');if(modal&&modal.textContent.indexOf('Organic traffic')!==-1){return{success:true,modal:modal,attempts:attempt+1};}if(hasTurnstileIframe()&&!focusRequested&&Date.now()-startTime>5000){focusRequested=true;var focusResult=await requestTurnstileFocus();}await new Promise(function(r){setTimeout(r,500);});}if(attempt<maxRetries-1){window.location.reload();await new Promise(function(r){setTimeout(r,5000);});}}return{success:false,error:'modal timeout after '+maxRetries+' attempts',attempts:maxRetries};}
var currentDomain='${domains}'.split(',')[0].trim();var allResults=[];var waitResult=await waitForModalWithFocusQueue(3);if(!waitResult.success){allResults.push({domain_name:currentDomain,error:waitResult.error,turnstile_retries:waitResult.attempts});return JSON.stringify({total_domains:1,results:allResults});}var modal=waitResult.modal;await new Promise(function(r){setTimeout(r,3000)});var organicTraffic=findMetricInModal(modal,'Organic traffic');var trafficValue=findMetricInModal(modal,'Traffic value');var countriesRaw=extractTableInModal(modal,'Top countries');var topCountries=countriesRaw.map(function(row){if(row.length>=2)return{country:row[0],traffic_share:row[row.length-1]};return{raw:row.join(' | ')};});var keywordsRaw=extractTableInModal(modal,'Top keywords');var topKeywords=keywordsRaw.map(function(row){if(row.length>=3)return{keyword:row[0],position:row[1],volume:row[2]};if(row.length===2)return{keyword:row[0],volume:row[1]};return{raw:row.join(' | ')};});var pagesRaw=extractTableInModal(modal,'Top pages');var topPages=pagesRaw.map(function(row){if(row.length>=3)return{url:row[0],traffic:row[1],traffic_percentage:row[2]};if(row.length===2)return{url:row[0],traffic:row[1]};return{raw:row.join(' | ')};});var trafficGraph=extractGraphData(modal);allResults.push({domain_name:currentDomain,organic_traffic:organicTraffic,traffic_value:trafficValue,traffic_graph:trafficGraph,top_countries:topCountries,top_keywords:topKeywords,top_pages:topPages,turnstile_retries:waitResult.attempts});return JSON.stringify({total_domains:1,results:allResults});
